#include "ui/TransportComponent.h"
namespace jeff::daw {TransportComponent::TransportComponent(AudioEngine&e):engine(e){play.onClick=[this]{engine.setPlaying(true);};stop.onClick=[this]{engine.setPlaying(false);};metro.onClick=[this]{engine.setMetronomeEnabled(metro.getToggleState());};tempo.setRange(20,300,1);tempo.setValue(120);tempo.setTextValueSuffix(" BPM");tempo.onValueChange=[this]{engine.setTempo(tempo.getValue());};for(auto*c:{(juce::Component*)&play,(juce::Component*)&stop,(juce::Component*)&metro,(juce::Component*)&tempo})addAndMakeVisible(*c);}void TransportComponent::resized(){auto r=getLocalBounds().reduced(4);play.setBounds(r.removeFromLeft(90));stop.setBounds(r.removeFromLeft(90));metro.setBounds(r.removeFromLeft(130));tempo.setBounds(r.removeFromLeft(220));}}
